"""Independent scalar BCE derivative/Hessian and every saved TRAIN update."""
import argparse,os,hashlib,numpy as np,torch
from pathlib import Path
import caltech20_rich_L6_binary_rest as m
import audit_caltech20_rich_pair50_alpha as saved
def independent_plan(stage,pred,w,b,used):
 tr,te=pred['train'],pred['test'];x=tr['features'].astype(float);z=te['features'].astype(float);guess=m.probabilities(z,w,b).argmax(1);bad=[i for i in range(len(guess)) if guess[i]!=te['labels'][i]];counts=[sum(te['labels'][i]==k for i in bad) for k in range(20)];options=sorted((k for k in range(20) if counts[k]>0 and k not in used),key=lambda k:(-int(counts[k]),k))
 if not options:return None
 k=options[0];errors=[i for i in bad if te['labels'][i]==k];pool=np.flatnonzero(tr['labels']==k);other=np.flatnonzero(tr['labels']!=k);xn=x/np.linalg.norm(x,axis=1,keepdims=True);zn=z/np.linalg.norm(z,axis=1,keepdims=True);items=[]
 for i in errors:items.extend(sorted(pool.tolist(),key=lambda j:(-float(xn[j]@zn[i]),j))[:3])
 z=x@w.T+b;hard=sorted(other.tolist(),key=lambda j:(-float(z[j,k]-z[j,tr['labels'][j]]),j))[:128];rg=np.random.default_rng(m.PROFILE['seed']+m.CASE*100000+stage);batches=[list(map(int,np.r_[rg.choice(items,16,replace=True),rg.choice(pool,16,replace=False),rg.choice(hard,16,replace=False),rg.choice(len(x),16,replace=False)])) for _ in range(m.PROFILE['steps_per_class'])];return dict(stage=stage,label=k,error_indices=errors,TRAIN_neighbors=items,hard_TRAIN=hard,batches=batches)
def independent_gradient(x,target,reference,q,u,v,u0,v0,family):
 c=m.PROFILE;n=len(x);d=x@u.astype(np.float32).astype(float)+float(np.float32(v))-reference;p=1/(1+np.exp(-np.clip(d,-60,60)));soft=1/(1+np.exp(-np.clip(d/c['temperature'],-60,60)));weight=np.ones(n);weight[:16]=c['neighbor_weight'];dz=(weight*c['temperature']*(soft-target)+c['KL']*(p-q))/n;g=x.T@dz+c['anchor']*(u-u0);h=float(dz.sum()+c['anchor']*(v-v0));cur=(weight*soft*(1-soft)+c['KL']*p*(1-p))/n;diagonal=(x*x).T@cur+c['anchor'];bd=float(cur.sum()+c['anchor']);stats=dict(diagonal_maxmin=float(diagonal.max()/diagonal.min()),diagonal_min=float(diagonal.min()),diagonal_max=float(diagonal.max()),preconditioned=family=='binary_rest_diagonal')
 if family=='binary_rest_diagonal':g=g/diagonal;h=h/bd
 return g,float(h),stats,diagonal,bd
def cpu():
 assert m.CASE==0 and not m.CPU.exists();m.claim(m.CPU.with_name(m.CPU.name+'.claim.json'),'independent_binary_derivative_Hessian_and_sampler');m.frozen();q=m.initial_parent();pt,pred=m.load_parent(q);w=pt['model']['linear.weight'].double().numpy();b=pt['model']['linear.bias'].double().numpy();pl=m.plan(1,pred,w,b,[]);assert pl==independent_plan(1,pred,w,b,[]);label=pl['label'];x,target,ref,teacher=m.prepared(pred,w,b,label);ix=np.array(pl['batches'][0]);xx=x[ix];t=target[ix];rr=ref[ix];qq=teacher[ix];u=w[label].copy();v=float(b[label]);vec=torch.tensor(np.r_[u,v],dtype=torch.float64,requires_grad=True);weights=np.ones(64);weights[:16]=m.PROFILE['neighbor_weight'];c=m.PROFILE
 def objective(uv):
  d=torch.tensor(xx)@uv[:-1]+uv[-1]-torch.tensor(rr);loss=(torch.tensor(weights)*torch.nn.functional.binary_cross_entropy_with_logits(d/c['temperature'],torch.tensor(t),reduction='none')).mean()*c['temperature']**2+c['KL']*torch.nn.functional.binary_cross_entropy_with_logits(d,torch.tensor(qq));return loss+c['anchor']/2*((uv-torch.tensor(np.r_[u,v])).square().sum())
 raw=torch.autograd.grad(objective(vec),vec)[0].detach().numpy();hd=torch.autograd.functional.hessian(objective,vec,vectorize=True).diagonal().detach().numpy();checks={}
 for family in c['families']:
  g,h,stats=m.gradient(xx,t,rr,qq,u,v,u,v,family);ig,ih,istat,diag,bd=independent_gradient(xx,t,rr,qq,u,v,u,v,family);reference=raw if family=='binary_rest' else raw/hd;err=max(float(np.max(abs(np.r_[g,h]-reference))),float(np.max(abs(g-ig))),abs(h-ih));herr=float(np.max(abs(np.r_[diag,bd]-hd)));assert err<1e-10 and herr<1e-10 and stats==istat and diag.min()>=c['anchor'] and bd>=c['anchor'];assert np.linalg.norm(g)>0;checks[family]=dict(gradient_maxabs=err,Hessian_diagonal_maxabs=herr,TRAIN_curvature_maxmin=stats['diagonal_maxmin'])
 assert not set(pred['train']['ids'])&set(pred['test']['ids']);m.CPU.mkdir();m.s.save(m.CPU/'checks.json',dict(m.identity(),passed=True,parent=q,label=label,checks=checks,real_optical_models=0,optical_forward=0,TEST_forward=0,optimizer_steps=0),exclusive=True);m.frozen()
def audit():
 assert m.CASE>0 and os.environ['CUDA_VISIBLE_DEVICES']=='' and not (m.OUT/'science').exists();m.claim(m.OUT/'audit_claim.json','independent_complete_binary_scalar_trajectory');meta=m.s.read(m.OUT/'metadata.json');ex=m.s.read(m.OUT/'producer_exit.json');assert ex['returncode']==0 and ex['actual_exit'] and not Path('/proc',str(ex['pid']),'cmdline').exists();assert meta['sources']==m.sources() and meta['config']==m.config();m.engine.verify_sources(meta['sources'],meta['git_commit']);fit=m.s.read(m.OUT/'fit_result.json');records=m.s.read(m.OUT/'stages.json');bestpt=torch.load(m.OUT/'best.pt',map_location='cpu',weights_only=False);lastpt=torch.load(m.OUT/'last.pt',map_location='cpu',weights_only=False);spec=m.specification();q=spec['parent'];assert fit['parent']==q;pt,pred=m.load_parent(q);w=pt['model']['linear.weight'].double().numpy().copy();b=pt['model']['linear.bias'].double().numpy().copy();initial=int((pred['test']['probabilities'].argmax(1)==pred['test']['labels']).sum());best=initial;used=[];updates=0;x=pred['train']['features'].astype(float);y=pred['train']['labels'];lastw,lastb=w.copy(),b.copy();c=m.PROFILE
 for stage,record in enumerate(records,1):
  pl=independent_plan(stage,pred,w,b,used);assert pl==record['plan'];label=pl['label'];used.append(label);z=x@w.T+b;other=z.copy();other[:,label]=-np.inf;mx=other.max(1);ref=mx+np.log(np.exp(other-mx[:,None]).sum(1));target=np.where(y==label,1-c['label_smoothing']/2,c['label_smoothing']/2);teacher=1/(1+np.exp(-np.clip(z[:,label]-ref,-60,60)));u0,v0=w[label].copy(),float(b[label]);u,v=u0.copy(),v0;mu,mv=np.zeros_like(u),0.;chosen=(u.copy(),v);selected=0
  for step,row in enumerate(record['trace'],1):
   ix=np.array(pl['batches'][step-1]);assert row['step']==step and row['indices']==ix.tolist();g,h,stats,_,_=independent_gradient(x[ix],target[ix],ref[ix],teacher[ix],u,v,u0,v0,spec['family']);scale=min(1.,1/(np.sqrt((g*g).sum()+h*h)+1e-6));mu=c['momentum']*mu+g*scale;mv=c['momentum']*mv+h*scale;u-=c['lr']*mu;v-=c['lr']*mv;scale=min(1.,c['row_radius']/max(np.sqrt(((u-u0)**2).sum()+(v-v0)**2),1e-12));u=u0+(u-u0)*scale;v=float(v0+(v-v0)*scale);ww,bb=w.copy(),b.copy();ww[label]=u;bb[label]=v;n=int((m.probabilities(pred['test']['features'],ww,bb).argmax(1)==pred['test']['labels']).sum());assert n==row['correct'] and stats==row['stats'];assert hashlib.sha256(u.tobytes()+np.array([v],dtype='<f8').tobytes()).hexdigest()==row['row_SHA256']
   if n>best:best=n;selected=step;chosen=(u.copy(),v)
   updates+=1
  lastw,lastb=w.copy(),b.copy();lastw[label]=u;lastb[label]=v;w[label]=chosen[0].astype(np.float32).astype(float);b[label]=float(np.float32(chosen[1]));assert record['selected_step']==selected and record['best_correct']==best;assert np.array_equal(w[label],np.array(record['retained_weight'])) and b[label]==record['retained_bias'];assert len(record['trace'])<=c['steps_per_class'] and (len(record['trace'])==c['steps_per_class'] or best>=c['target_correct'])
 assert len(records)<=c['maximum_classes'] and fit['initial_correct']==initial and fit['selected_correct']==best and fit['actual_updates']==updates;assert fit['strictly_improved']==(best>initial) and fit['target_achieved']==(best>=c['target_correct']);assert np.array_equal(bestpt['model']['linear.weight'].numpy(),w) and np.array_equal(bestpt['model']['linear.bias'].numpy(),b);assert np.array_equal(lastpt['model']['linear.weight'].numpy(),lastw.astype(np.float32)) and np.array_equal(lastpt['model']['linear.bias'].numpy(),lastb.astype(np.float32));assert all(torch.equal(v,bestpt['model'][k]) for k,v in pt['model'].items() if not k.startswith('linear.'));untouched=[i for i in range(20) if i not in used];assert np.array_equal(bestpt['model']['linear.weight'].numpy()[untouched],pt['model']['linear.weight'].numpy()[untouched]) and np.array_equal(bestpt['model']['linear.bias'].numpy()[untouched],pt['model']['linear.bias'].numpy()[untouched])
 for role in ('train','val','test'):metrics,_=saved.verify_predictions(m.OUT/('selected_'+role+'.npz'),bestpt['model'],role,m.base.manifest());saved.agree(metrics,fit['metrics'][role]);saved.agree(metrics,bestpt['metrics'][role])
 for file,sha in fit['hashes'].items():assert m.s.sha(m.OUT/file)==sha
 m.frozen();(m.OUT/'science').mkdir();m.s.save(m.OUT/'science/audit.json',dict(passed=True,sources=meta['sources'],training_commit=meta['git_commit'],case=m.CASE,family=spec['family'],correct=best,actual_updates=updates,sampler_and_full_gradient_curvature_trajectory_replayed=True,nonhead_bytes_unchanged=True,only_one_row_updated_per_stage=True,L2_L4_not_loaded_or_trained=True,optical_forward=0,TEST_informed_development=True,independent_generalization=False),exclusive=True)
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--phase',choices=['cpu','audit'],required=True);a=p.parse_args()
 try:cpu() if a.phase=='cpu' else audit()
 except BaseException as e:
  p=m.CPU.with_name(m.CPU.name+'.failure.json') if a.phase=='cpu' else m.OUT/'audit_failure.json'
  if not p.exists():m.s.save(p,dict(error=repr(e),automatic_retry=False),exclusive=True)
  raise
